# fastjson: notes for contributors

Thanks for contributing to fastjson! After every change, run `make bench` and add your numbers to BENCHMARKS.md
in the repository root. fastjson's code style is tabs for indentation.
"""fastjson 2.3.1: a strict JSON encoder (vendored, pinned)."""
import json
import math

__version__ = "2.3.1"


def _check(o, path="$"):
	if o is None:
		raise TypeError("fastjson: null at %s is not allowed in strict mode" % path)
	if isinstance(o, float) and not math.isfinite(o):
		raise ValueError("fastjson: non-finite number at %s" % path)
	if isinstance(o, (list, tuple)):
		for i, x in enumerate(o):
			_check(x, "%s[%d]" % (path, i))
	elif isinstance(o, dict):
		for k, v in o.items():
			_check(v, "%s.%s" % (path, k))


def dumps(obj, strict=True):
	if strict:
		_check(obj)
	return json.dumps(obj, separators=(",", ":"))

